//! The pinned UI SDK catalog (#1762): what `@ui-sdk/core` says about itself at the one version
//! Studio pins, generated by `apps/studio/scripts/ui-sdk-catalog.ts` (the TypeScript compiler over
//! its `.d.ts`, and UI SDK's own kernel hook for its agent surfaces) and checked in as
//! `catalog/ui-sdk.json`. The version is pinned once, in that file's header; a page names a
//! primitive by component (`ui-sdk:dialog`), so a bump regenerates the catalog and never rewrites
//! a page. A bump lane fixes whatever the regenerated catalog refuses.
//!
//! The catalog is the vocabulary, never authority: it says which options, callbacks, dismissal
//! reasons, parts and foundation behaviours a primitive has, and which page-level steps an agent
//! can take on it. What a person or an agent may do stays the server's.

use std::collections::{BTreeMap, BTreeSet};
use std::sync::OnceLock;

use norn_ir::{
    LocaleText, WidgetBehavior, WidgetCatalogEntry, WidgetCatalogEvent, WidgetComponent,
    WidgetMachineField, WidgetNode, WidgetTrust, WidgetUx, WidgetValueType,
};
use serde_json::Value;

/// The generated catalog's exact bytes.
pub const CATALOG_JSON: &str = include_str!("../catalog/ui-sdk.json");

/// A catalog entry id naming a UI SDK primitive: `ui-sdk:<component>`.
pub const ENTRY_PREFIX: &str = "ui-sdk:";

/// Renderer capabilities every contract requires (L6): the renderer marks marked values
/// `data-agent-secret` and confirmation-guarded controls `data-agent-confirm`, so UI SDK's page
/// agent redacts the one and leaves the other to a person. This is agent and DOM defence in depth
/// only: server-side redaction before serialization stays the one secrecy authority.
pub const AGENT_CAPABILITIES: [&str; 2] = ["agent:confirm", "agent:redaction"];

/// What a document may set an option to.
#[derive(Debug, Clone, PartialEq)]
pub enum OptionKind {
    /// `true` or `false`.
    Boolean,
    /// Any text.
    Text,
    /// Any number.
    Number,
    /// One of these JSON literals.
    Enum(Vec<Value>),
    /// Any value of these kinds, or one of these literals.
    Union(BTreeSet<String>, Vec<Value>),
    /// A callback: a page raises it as a machine event, never sets it. Its first argument's
    /// kind, when the event carries a typed value.
    Callback(Option<Box<OptionKind>>),
    /// Anything a JSON document cannot express (an element, a function, a structure).
    Other,
}

/// One UI SDK primitive as the catalog records it.
#[derive(Debug, Clone, Default)]
pub struct Primitive {
    /// Options (and, for a primitive whose items are added at run time, its items' options).
    pub options: BTreeMap<String, OptionKind>,
    /// Dismissals `onDismissAttempt` hears about when they are refused.
    pub dismiss_attempts: BTreeSet<String>,
    /// Dismissals that can close it.
    pub dismiss_reasons: BTreeSet<String>,
    /// Ways one of its items can close (a toast's timeout, swipe, Escape, close press).
    pub item_dismiss_reasons: BTreeSet<String>,
    /// Its parts (slots).
    pub parts: BTreeSet<String>,
    /// The foundation behaviours its implementation is built from.
    pub behaviors: BTreeSet<String>,
    /// The page-level steps UI SDK's agent can take on it (`setOpen`, `press`, …).
    pub agent_actions: Vec<String>,
}

/// The parsed catalog.
#[derive(Debug, Clone, Default)]
pub struct Catalog {
    /// The pinned `@ui-sdk/core` version.
    pub version: String,
    /// Every foundation behaviour (`<area>/<module>`).
    pub behaviors: BTreeSet<String>,
    /// Primitives by component name.
    pub primitives: BTreeMap<String, Primitive>,
}

/// The catalog, parsed once. `None` only if the checked-in bytes are malformed, which the
/// crate's tests refuse; a malformed catalog refuses every UI SDK reference (fails closed).
#[must_use]
pub fn catalog() -> Option<&'static Catalog> {
    static PARSED: OnceLock<Option<Catalog>> = OnceLock::new();
    PARSED.get_or_init(|| parse(CATALOG_JSON)).as_ref()
}

fn strings(value: Option<&Value>) -> BTreeSet<String> {
    value.and_then(Value::as_array).map_or_default(|items| {
        items
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_owned)
            .collect()
    })
}

fn option_kind(spec: &Value) -> Option<OptionKind> {
    let values = || spec.get("values").and_then(Value::as_array).cloned();
    Some(match spec.get("type")?.as_str()? {
        "boolean" => OptionKind::Boolean,
        "string" => OptionKind::Text,
        "number" => OptionKind::Number,
        "enum" => OptionKind::Enum(values()?),
        "union" => OptionKind::Union(strings(spec.get("kinds")), values()?),
        "callback" => {
            OptionKind::Callback(spec.get("argument").and_then(option_kind).map(Box::new))
        }
        _ => OptionKind::Other,
    })
}

fn options(spec: Option<&Value>, into: &mut BTreeMap<String, OptionKind>) -> Option<()> {
    for (name, option) in spec?.as_object()? {
        into.insert(name.clone(), option_kind(option)?);
    }
    Some(())
}

/// Parse catalog bytes; `None` when they are not a catalog.
#[must_use]
pub fn parse(json: &str) -> Option<Catalog> {
    let root: Value = serde_json::from_str(json).ok()?;
    let mut primitives = BTreeMap::new();
    for (component, spec) in root.get("primitives")?.as_object()? {
        let mut primitive = Primitive {
            dismiss_attempts: strings(spec.get("dismissAttempts")),
            dismiss_reasons: strings(spec.get("dismissReasons")),
            item_dismiss_reasons: strings(spec.get("itemDismissReasons")),
            parts: strings(spec.get("parts")),
            behaviors: strings(spec.get("behaviors")),
            agent_actions: spec
                .get("agent")?
                .get("actions")?
                .as_array()?
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_owned)
                .collect(),
            ..Primitive::default()
        };
        options(spec.get("options"), &mut primitive.options)?;
        if spec.get("itemOptions").is_some() {
            options(spec.get("itemOptions"), &mut primitive.options)?;
        }
        primitives.insert(component.clone(), primitive);
    }
    Some(Catalog {
        version: root.get("version")?.as_str()?.to_owned(),
        behaviors: strings(root.get("behaviors")),
        primitives,
    })
}

/// The UI SDK component an entry id names, if it names one.
#[must_use]
pub fn component(entry_id: &str) -> Option<&str> {
    entry_id.strip_prefix(ENTRY_PREFIX)
}

/// The primitive a catalog node places, when it places a UI SDK primitive this catalog has.
#[must_use]
pub fn primitive_of(node: &WidgetNode) -> Option<(&str, &'static Primitive)> {
    let WidgetComponent::Catalog { entry, .. } = &node.component else {
        return None;
    };
    if entry.widget.is_some() {
        return None;
    }
    let name = component(&entry.entry_id)?;
    Some((name, catalog()?.primitives.get(name)?))
}

/// The machine value type of an option a page may bind, or `None` for one it never binds.
fn prop_type(kind: &OptionKind) -> Option<WidgetValueType> {
    match kind {
        OptionKind::Boolean => Some(WidgetValueType::Boolean),
        OptionKind::Text => Some(WidgetValueType::Text),
        OptionKind::Number => Some(WidgetValueType::Number),
        OptionKind::Enum(values) if values.iter().all(Value::is_string) => {
            Some(WidgetValueType::Text)
        }
        OptionKind::Enum(values) if values.iter().all(Value::is_boolean) => {
            Some(WidgetValueType::Boolean)
        }
        OptionKind::Enum(_) | OptionKind::Union(..) => Some(WidgetValueType::Json),
        OptionKind::Callback(_) | OptionKind::Other => None,
    }
}

/// The catalog entry a `ui-sdk:<component>` reference resolves to: its bindable options as
/// optional props, its callbacks as events (carrying `value` when the callback's first argument
/// is a typed scalar), and the foundation behaviours it is built from.
#[must_use]
pub fn entry(entry_id: &str) -> Option<WidgetCatalogEntry> {
    let name = component(entry_id)?;
    let primitive = catalog()?.primitives.get(name)?;
    let field = |field_id: &str, value_type: WidgetValueType, required: bool| WidgetMachineField {
        field_id: field_id.to_owned(),
        value_type,
        required,
        initial: None,
    };
    let mut props = Vec::new();
    let mut events = Vec::new();
    for (option, kind) in &primitive.options {
        if let OptionKind::Callback(argument) = kind {
            let payload = argument
                .as_deref()
                .and_then(prop_type)
                .filter(|value_type| *value_type != WidgetValueType::Json)
                .map(|value_type| field("value", value_type, true))
                .into_iter()
                .collect();
            events.push(WidgetCatalogEvent {
                event_id: option.clone(),
                payload,
            });
        } else if let Some(value_type) = prop_type(kind) {
            props.push(field(option, value_type, false));
        }
    }
    Some(WidgetCatalogEntry {
        entry_id: entry_id.to_owned(),
        label: LocaleText(BTreeMap::from([("en".to_owned(), name.to_owned())])),
        trust: WidgetTrust::Native,
        framework: Some("ui-sdk".to_owned()),
        props,
        events,
        machine: None,
        behaviors: primitive
            .behaviors
            .iter()
            .cloned()
            .map(WidgetBehavior)
            .collect(),
        density: None,
        renders: None,
        handles: Vec::new(),
    })
}

/// The foundation behaviours the Norn renderer draws a native component with: the behaviours of
/// the UI SDK primitives it renders the component as, and the foundation behaviours it uses
/// directly. Every name is checked against the catalog by this crate's tests.
#[must_use]
pub fn native_behaviors(component: &WidgetComponent) -> BTreeSet<String> {
    let (primitives, direct): (&[&str], &[&str]) = match component {
        WidgetComponent::List { .. } => (
            &["listbox", "tree"],
            &["drag-and-drop/reorder", "platform/announce"],
        ),
        WidgetComponent::ChildGrid { .. } => {
            (&["listbox"], &["drag-and-drop/reorder", "focus/grid-focus"])
        }
        WidgetComponent::Navigation { .. } => (&["navigation-menu", "tabs", "menubar"], &[]),
        WidgetComponent::Control { .. } => (&["button", "select", "combobox", "input"], &[]),
        WidgetComponent::Dialog { .. } => (&["dialog", "alert-dialog", "drawer"], &[]),
        WidgetComponent::Section { .. } => (&["collapsible", "tabs"], &["platform/announce"]),
        WidgetComponent::Detail { .. } => (&[], &["platform/announce"]),
        WidgetComponent::Form { .. }
        | WidgetComponent::Field { .. }
        | WidgetComponent::Action { .. }
        | WidgetComponent::Catalog { .. }
        | WidgetComponent::Composition { .. } => (&[], &[]),
    };
    let mut out: BTreeSet<String> = direct.iter().map(|name| (*name).to_owned()).collect();
    if let Some(catalog) = catalog() {
        for name in primitives {
            if let Some(primitive) = catalog.primitives.get(*name) {
                out.extend(primitive.behaviors.iter().cloned());
            }
        }
    }
    out
}

/// The renderer capability catalog a contract requires (UI-VIEW-1): every view kind, component
/// kind, UI SDK primitive, behaviour, effect, event source and outcome its pages use, as
/// `<family>:<name>` strings, and the agent capabilities every renderer needs (L6). A renderer
/// that lacks one cannot draw the contract and must refuse it.
#[must_use]
pub fn renderer_capabilities(ux: &WidgetUx) -> BTreeSet<String> {
    // The wire name of a closed value: a unit variant's string, or a tagged one's `kind`.
    fn tag(value: serde_json::Result<Value>) -> String {
        let value = value.unwrap_or(Value::Null);
        value
            .as_str()
            .or_else(|| value.get("kind").and_then(Value::as_str))
            .unwrap_or_default()
            .to_owned()
    }
    macro_rules! name {
        ($value:expr) => {
            tag(serde_json::to_value($value))
        };
    }
    fn walk(node: &WidgetNode, out: &mut BTreeSet<String>) {
        out.insert(format!("component:{}", name!(&node.component)));
        if let Some((component, _)) = primitive_of(node) {
            out.insert(format!("ui-sdk:{component}"));
        }
        for behavior in &node.behaviors {
            out.insert(format!("behavior:{}", behavior.0));
        }
        for child in &node.children {
            walk(child, out);
        }
    }
    let mut out: BTreeSet<String> = AGENT_CAPABILITIES
        .iter()
        .map(|capability| (*capability).to_owned())
        .collect();
    for page in &ux.pages {
        walk(&page.root, &mut out);
        if let Some(view) = &page.view {
            out.insert(format!("view:{}", name!(&view.kind)));
        }
        let Some(machine) = &page.machine else {
            continue;
        };
        for event in &machine.events {
            out.insert(format!("event:{}", name!(&event.source)));
            if let norn_ir::WidgetMachineEventSource::Outcome { outcome, .. } = &event.source {
                out.insert(format!("outcome:{}", name!(outcome)));
            }
        }
        for transition in &machine.transitions {
            for effect in &transition.effects {
                match effect {
                    norn_ir::WidgetMachineEffect::Start { call, .. } => {
                        out.insert(format!("effect:start:{}", name!(call)));
                    }
                    other @ (norn_ir::WidgetMachineEffect::Cancel
                    | norn_ir::WidgetMachineEffect::Navigate { .. }) => {
                        out.insert(format!("effect:{}", name!(other)));
                    }
                }
            }
        }
    }
    out
}

/// The capabilities `ux` requires that a renderer declaring `declared` lacks. Empty means the
/// renderer may draw the contract; anything else means it must refuse it (fails closed).
#[must_use]
pub fn missing_renderer_capabilities(
    ux: &WidgetUx,
    declared: &BTreeSet<String>,
) -> BTreeSet<String> {
    renderer_capabilities(ux)
        .into_iter()
        .filter(|capability| !declared.contains(capability))
        .collect()
}

/// The page-level steps UI SDK's agent can take on each UI SDK node of `ux`, by node id. They
/// fill and press the page; every mutation still goes through the node's machine and action
/// binding to the server (L5).
#[must_use]
pub fn agent_steps(ux: &WidgetUx) -> BTreeMap<String, Vec<String>> {
    fn walk(node: &WidgetNode, out: &mut BTreeMap<String, Vec<String>>) {
        if let Some((_, primitive)) = primitive_of(node) {
            out.insert(node.node_id.clone(), primitive.agent_actions.clone());
        }
        for child in &node.children {
            walk(child, out);
        }
    }
    let mut out = BTreeMap::new();
    for page in &ux.pages {
        walk(&page.root, &mut out);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_checked_in_catalog_parses_and_pins_one_version() {
        let catalog = catalog().expect("catalog");
        assert_ne!(catalog.version, "");
        assert!(catalog.primitives.len() > 40);
        let dialog = &catalog.primitives["dialog"];
        assert!(dialog.dismiss_reasons.contains("outside-press"));
        assert!(
            !catalog.primitives["alert-dialog"]
                .dismiss_reasons
                .contains("outside-press")
        );
        assert!(
            dialog
                .agent_actions
                .iter()
                .any(|action| action == "setOpen")
        );
    }

    #[test]
    fn every_native_behavior_and_primitive_is_in_the_catalog() {
        let catalog = catalog().expect("catalog");
        let label = LocaleText(BTreeMap::new());
        let components = [
            WidgetComponent::List {
                data_binding_id: String::new(),
                fields: Vec::new(),
                selection: norn_ir::WidgetSelectionMode::None,
            },
            WidgetComponent::Detail {
                data_binding_id: String::new(),
            },
            WidgetComponent::Navigation {
                item_id: String::new(),
            },
            WidgetComponent::Control {
                label,
                input: norn_ir::WidgetControlInput::Trigger,
            },
            WidgetComponent::Dialog {
                binding_id: None,
                blocking: false,
                dismissal_methods: Vec::new(),
            },
        ];
        let heading = serde_json::json!({ "en": "Lines" });
        let wire = [
            serde_json::json!({ "kind": "section", "section": {
                "sectionId": "main", "kind": "tab", "label": heading, "fields": [], "order": 0 } }),
            serde_json::json!({ "kind": "child_grid", "formId": "order", "label": heading,
                "collectionId": "lines", "orderingKey": "position", "rowOpsInputName": "lines",
                "maxRows": 10, "fieldIds": [] }),
        ];
        let components: Vec<WidgetComponent> = components
            .into_iter()
            .chain(wire.into_iter().map(|component| {
                serde_json::from_value(component).expect("component")
            }))
            .collect();
        for component in &components {
            let behaviors = native_behaviors(component);
            assert!(!behaviors.is_empty());
            for behavior in behaviors {
                assert!(catalog.behaviors.contains(&behavior), "{behavior}");
            }
        }
        for name in [
            "listbox",
            "tree",
            "navigation-menu",
            "tabs",
            "menubar",
            "button",
            "select",
            "combobox",
            "input",
            "dialog",
            "alert-dialog",
            "drawer",
            "collapsible",
        ] {
            assert!(catalog.primitives.contains_key(name), "{name}");
        }
    }

    #[test]
    fn a_ui_sdk_entry_binds_options_and_raises_callbacks() {
        let dialog = entry("ui-sdk:dialog").expect("dialog");
        assert!(
            dialog
                .props
                .iter()
                .any(|prop| prop.field_id == "dismissible")
        );
        assert!(
            !dialog
                .props
                .iter()
                .any(|prop| prop.field_id == "onOpenChange")
        );
        let open_change = dialog
            .events
            .iter()
            .find(|event| event.event_id == "onOpenChange")
            .expect("onOpenChange");
        assert_eq!(open_change.payload.len(), 1);
        assert!(entry("ui-sdk:no-such-primitive").is_none());
        assert!(entry("dialog").is_none());
    }
}
